import{_ as t,o as n,c as a,a2 as o}from"./chunks/framework.CfwCq2QB.js";const r="/dev-go-docs/shots/0.2.3/en/light/sync-backup-card.png",m=JSON.parse('{"title":"Backup & sync","description":"","frontmatter":{},"headers":[],"relativePath":"en/settings/sync.md","filePath":"en/settings/sync.md"}'),s={name:"en/settings/sync.md"};function i(c,e,d,l,p,h){return n(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="backup-sync" tabindex="-1">Backup &amp; sync <a class="header-anchor" href="#backup-sync" aria-label="Permalink to &quot;Backup &amp; sync&quot;">​</a></h1><p>In one line: export all settings to JSON and import them elsewhere (moving machines, keeping a backup); data that needs to stay in sync across devices syncs automatically in the background — just sign in to the same browser account.</p><h2 id="backup-export-import" tabindex="-1">Backup (export / import) <a class="header-anchor" href="#backup-export-import" aria-label="Permalink to &quot;Backup (export / import)&quot;">​</a></h2><p>Under Settings → General → Backup:</p><ul><li><strong>Export</strong>: writes a JSON file with everything — quick links, network and proxy, translation, AI models, selection actions and site lists, page enhancements, appearance and language</li><li><strong>Import</strong>: pick the file and it takes effect immediately; invalid entries are skipped with &quot;Imported N items (skipped M invalid)&quot;</li><li>Backup files carry an app marker and version; anything that isn&#39;t a DevGo backup is rejected outright</li></ul><img src="'+r+'" alt="The Backup card: Export and Import"><p><em>The &quot;Backup&quot; card — export / import your configuration; API keys never enter backup files.</em></p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p><strong>API keys are never written to backup files</strong> (to avoid leaking secrets in plain text). After importing on a new machine, re-enter the keys under <a href="/dev-go-docs/en/settings/models.html">AI models</a>.</p></div><h2 id="sync-across-devices" tabindex="-1">Sync across devices <a class="header-anchor" href="#sync-across-devices" aria-label="Permalink to &quot;Sync across devices&quot;">​</a></h2><p>No export/import needed: signed in to the same browser account (Chrome account sync), the following travel to your other devices automatically:</p><ul><li><strong>Quick links</strong> (new tab sites, categories, pinned row)</li><li><strong>Proxy configuration</strong> (network mode, proxy servers, rule lists)</li></ul><p>Sync runs in the background in chunks; oversized items or a full sync quota (100KB on Chrome) surface under General → Sync across devices, and &quot;Sync now&quot; triggers a manual run. Whether DevGo takes over the browser proxy is confirmed per device in the Network panel — never pushed through sync.</p><h2 id="which-one-when" tabindex="-1">Which one when? <a class="header-anchor" href="#which-one-when" aria-label="Permalink to &quot;Which one when?&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Scenario</th><th>Recommendation</th></tr></thead><tbody><tr><td>New computer / browser reinstall</td><td>Export → import; one move, everything lands</td></tr><tr><td>Keeping several devices in sync day to day</td><td>Sign in to the same browser account; sync does the work</td></tr><tr><td>Moving quick links only</td><td>The new tab&#39;s own import / export (links only) is lighter</td></tr></tbody></table>',14)])])}const k=t(s,[["render",i]]);export{m as __pageData,k as default};
